/**
 * Game server control panel — SSH/RCON transport + per-family control facts.
 *
 * A plain server-side module (NO "use server", no client imports). Imported by
 * BOTH the server actions (lib/actions-game-control.ts) and the worker
 * (worker/game-control.ts). It NEVER runs in the browser — the customer's root
 * credentials and their server's RCON password stay on our server.
 *
 * Everything here operates on the CUSTOMER'S OWN game VM over the platform's
 * existing SSH (host/port/root-password derived exactly like lib/sftp.ts, reused
 * via lib/ssh-exec.ts `withServerSsh`). Two transport rules, mirroring the rest of
 * the control panel:
 *
 *   1. STRICT ALLOWLIST VALIDATION for anything that reaches a shell. Ports, unit
 *      names, paths and file names are validated/allowlisted or rejected — never
 *      sanitized. Family/unit hints are compile-time constants, never customer
 *      input.
 *
 *   2. RCON never touches a shell at all. We read the server's RCON port/password
 *      out of its own config file, then open a TCP channel to 127.0.0.1:<port> on
 *      the game VM THROUGH the SSH connection (`conn.forwardOut`) and speak the
 *      Source RCON wire protocol directly. The RCON port is never exposed off the
 *      box, the password is only ever a protocol packet body (not an argv token),
 *      and the customer's console command is validated to be single-line/control-
 *      char-free before it is sent.
 *
 * SANDBOX: callers gate real SSH behind `!SANDBOX`; on staging the inline reads
 * return realistic synthetic data so the whole UX works without a live VM.
 */
import type { Duplex } from "node:stream";
import type { Client } from "ssh2";
import { GAME_FAMILIES, type GameFamily } from "./games";
import { exec, QUICK_TIMEOUT_MS } from "./ssh-exec";

// ---------------------------------------------------------------------------
// Per-family control facts
// ---------------------------------------------------------------------------

/** How (if at all) we can talk to a running server's console remotely. */
export type RconProtocol =
  | "source" // Valve Source RCON (Minecraft, CS2, Palworld) — implemented here
  | "rust-web" // Rust WebSocket RCON — different protocol, deferred
  | "none"; // no remote console protocol (Valheim/Terraria vanilla)

/** Where a family stores the RCON credentials, and how to parse that file. */
type RconConfig = {
  /** Config-file path candidates to try first (absolute). */
  candidates: string[];
  /** Roots to bounded-`find` under if none of the candidates exist. */
  findRoots: string[];
  /** File name to find. */
  findName: string;
  /** File format. */
  kind: "properties" | "palworld-ini";
  /** Key that gates RCON being on (value compared case-insensitively to true/1). */
  enableKey?: string;
  /** Key holding the RCON password. */
  passwordKey: string;
  /** Key holding the RCON port (falls back to `defaultPort`). */
  portKey?: string;
  /** Port used when the file does not specify one. */
  defaultPort: number;
};

export type GameControlSpec = {
  family: GameFamily;
  label: string;
  /** systemd unit-name hints (first that resolves wins). Compile-time constants. */
  serviceHints: string[];
  /** Directory candidates that hold the world/save data (for listing + backup). */
  dataRoots: string[];
  /** Remote console protocol. */
  rcon: RconProtocol;
  /** Where/how to read RCON creds (present only when rcon === "source"). */
  rconConfig?: RconConfig;
  /** RCON verb that lists connected players (present when supported). */
  listCommand?: string;
  /** RCON verb template for kicking a player (`%s` = validated name/id). */
  kickCommand?: string;
  /** RCON verb template for banning a player (`%s` = validated name/id). */
  banCommand?: string;
};

/**
 * The control facts per game family.
 *
 * RCON reality (why not every "has RCON" game gets a wire here):
 *  - minecraft: native Source RCON (enable-rcon / rcon.password / rcon.port).
 *  - cs2:       native Source RCON (rcon_password; port defaults to the game port).
 *  - palworld:  native RCON, Source-protocol framing (RCONEnabled/RCONPort/AdminPassword).
 *  - rust:      RCON is WebSocket (rcon.web) — a DIFFERENT protocol; deferred.
 *  - valheim:   no native RCON (needs a BepInEx mod) — console disabled.
 *  - terraria:  vanilla has only a local stdin console — console disabled.
 */
export const GAME_CONTROL: Record<GameFamily, GameControlSpec> = {
  minecraft: {
    family: "minecraft",
    label: "Minecraft",
    serviceHints: ["minecraft", "minecraft-server"],
    // `/opt/mc` is first because it's the actual host bind-mount the paid
    // template's setup script uses (`-v /opt/mc:/data`, prisma/catalog.ts) —
    // without it here, world listing silently found nothing while RCON
    // commands kept working (RCON config discovery falls back to a broader
    // `find` via `findRoots` below, which happened to still locate it).
    dataRoots: ["/opt/mc", "/opt/minecraft", "/srv/minecraft", "/home/minecraft", "/root/minecraft", "/minecraft"],
    rcon: "source",
    rconConfig: {
      candidates: [
        "/opt/mc/server.properties",
        "/opt/minecraft/server.properties",
        "/srv/minecraft/server.properties",
        "/home/minecraft/server.properties",
        "/root/minecraft/server.properties",
      ],
      findRoots: ["/opt", "/srv", "/home"],
      findName: "server.properties",
      kind: "properties",
      enableKey: "enable-rcon",
      passwordKey: "rcon.password",
      portKey: "rcon.port",

/**
 * Wave 9 games — make Mordhau, The Isle, Stationeers, Eco (Eco Global Survival)
 * and Empyrion: Galactic Survival orderable. Same Docker/OsTemplate pattern as
 * Waves 1-4/7/8: each is a community Docker image (wrapping SteamCMD, +Wine
 * where the dedicated-server build is Windows-only) installed by the
 * OsTemplate.setupScript in cloud-init, reusing the existing generic
 * worker/game-control.ts + lib/game-control.ts machinery. Researched 2026-08-31
 * against each game's official dedicated-server docs / SteamDB / community
 * Docker images — all five have real, currently-shipping dedicated server
 * support (none are P2P/lobby-only or require a non-anonymous Steam login,
 * unlike DayZ which stayed unseeded in Wave 4 — see lib/games.ts).
 *
 * Steam App IDs (dedicated server, NOT the game client) / install method:
 *   mordhau       629800   (Mordhau Dedicated Server — native Linux)
 *   theisle       412680   (The Isle Dedicated Server, "-beta evrima" branch — native Linux;
 *                           the default/legacy branch is obsolete and will NOT match modern
 *                           clients, so the image is pinned to the evrima branch explicitly)
 *   stationeers   600760   (Stationeers Dedicated Server — native Linux)
 *   eco           739590   ("Eco Server" Steam Tool, distinct from the 382310 client app —
 *                           confirmed anonymous-SteamCMD-installable per LinuxGSM + community
 *                           docs, NOT locked behind a linked Strange Loop account the way the
 *                           website-download path is; native cross-platform .NET server)
 *   empyrion      530870   (Empyrion - Galactic Survival Dedicated Server — Windows-only
 *                           build, no native Linux server exists, hence the Wine image)
 *
 * Docker images: mordhau uses cm2network/mordhau, the same publisher already
 * trusted elsewhere in this catalog for tf2 (Wave 4) — a long-running,
 * actively-maintained Source/UE4 dedicated-server image family. theisle uses
 * ghcr.io/auhrus/theisleevrima (Auhrus/theisle-evrima-docker-server on GitHub),
 * the most widely-referenced community image for Evrima specifically, with
 * explicit STEAMBRANCH support (needed for the evrima pin above). stationeers
 * uses didstopia/stationeers-server — actively maintained, clearly documented
 * env vars, exposes both the game and Steam-query ports. eco uses
 * emackie/steamcmd-eco, a straightforward SteamCMD-wrapper image (the
 * "official" strangeloopgames/eco-game-server image has no usage docs at all,
 * so the documented community image was chosen instead, matching this wave's
 * "pick one trustworthy community image" mandate). empyrion uses
 * bitr/empyrion-server, a Wine+SteamCMD image following the same Wine-wrapping
 * approach already used for sunkenland/icarus/abioticfactor/arkasa.
 *
 * Config-via-mounted-file games: theisle and empyrion do NOT expose server
 * name/password/slot-count as docker env vars in their community images (The
 * Isle configures via Game.ini inside the mounted volume; Empyrion via
 * dedicated.yaml inside the mounted Steam dir) — same precedent as Wave 3/4's
 * customer-specific values with no sane platform default (Dragonwilds'
 * OWNER_ID, DST's TOKEN): the container boots and is reachable with sane
 * defaults out of the box, and the customer edits the mounted config file
 * post-deploy via SFTP for anything further (server name, password, slots).
 *
 * RCON: all five ship with rcon:"none" in lib/game-control.ts even though the
 * underlying engines have real consoles (Mordhau/UE4 remote console, Source-
 * style query for others) — mirrors Wave 3/4/8's own precedent of not
 * reverse-engineering a brand-new community image's internal layout without a
 * live box to confirm paths against.
 *
 * NOTE: static in-container placeholder passwords ("changeme12"/blank) —
 * customers change them post-deploy, matching every prior wave.
 *
 * Run: cd /opt/nxeon-staging && npx tsx prisma/seed-wave9-games.ts   (idempotent)
 */
import { PrismaClient } from "@prisma/client";

const db = new PrismaClient();

type Template = { family: string; name: string; setupScript: string; minRamMB: number; minDiskGB: number };

const TEMPLATES: Template[] = [
  {
    family: "mordhau", name: "Mordhau Server", minRamMB: 4096, minDiskGB: 20,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/mordhau && docker run -d --name mordhau --restart unless-stopped --stop-timeout 30 -p 7777:7777/udp -p 27015:27015/udp -p 15000:15000/udp -e SERVER_NAME='Nxeon' -e SERVER_ADMINPW='changeme12' -e SERVER_PW='' -e SERVER_MAXPLAYERS='32' -e SERVER_PORT='7777' -e SERVER_QUERYPORT='27015' -e SERVER_BEACONPORT='15000' -v /opt/mordhau:/home/steam/mordhau-dedicated/ cm2network/mordhau:latest`,
  },
  {
    family: "theisle", name: "The Isle Server", minRamMB: 12288, minDiskGB: 40,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/theisle && chown -R 1000:1000 /opt/theisle && docker run -d --name theisle --restart unless-stopped --stop-timeout 30 -p 7777:7777/tcp -p 7777:7777/udp -p 10000:10000/tcp -e steambranch='evrima' -e updateonstart='true' -v /opt/theisle:"/home/steam/Steam/steamapps/common/The Isle Dedicated Server" ghcr.io/auhrus/theisleevrima:latest`,
  },
  {
    family: "stationeers", name: "Stationeers Server", minRamMB: 4096, minDiskGB: 20,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/stationeers && docker run -d --name stationeers --restart unless-stopped -p 27500:27500/tcp -p 27500:27500/udp -p 27015:27015/udp -e STATIONEERS_SERVER_NAME='Nxeon' -e STATIONEERS_WORLD_NAME='Nxeon World' -e STATIONEERS_SERVER_PASSWORD='' -e STATIONEERS_GAME_PORT='27500' -e STATIONEERS_QUERY_PORT='27015' -v /opt/stationeers:/steamcmd/stationeers didstopia/stationeers-server:latest`,
  },
  {
    family: "eco", name: "Eco Server", minRamMB: 8192, minDiskGB: 25,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/eco && docker run -d --name eco --restart unless-stopped -p 3000:3000/tcp -p 3001:3001/tcp -v /opt/eco:/eco emackie/steamcmd-eco:latest`,
  },
  {
    family: "empyrion", name: "Empyrion: Galactic Survival Server", minRamMB: 8192, minDiskGB: 30,
    setupScript: `curl -fsSL https://get.docker.com | sh && mkdir -p /opt/empyrion && docker run -d --name empyrion --restart unless-stopped -p 30000-30003:30000-30003/udp -v /opt/empyrion:/home/user/Steam bitr/empyrion-server:latest`,
  },
];

type TierSpec = { gameFamily: string; name: string; ramMB: number; cpuCores: number; diskGB: number; slots: number; priceCents: number; featured?: boolean };

const TIERS: TierSpec[] = [
  // Mordhau — FPS melee combat, official cap up to 64 players; priced on the
  // same scale as Wave 4's tf2/l4d2 Source-engine FPS tiers.
  { gameFamily: "mordhau", name: "Mordhau — 4 GB / 24 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 24, priceCents: 899 },
  { gameFamily: "mordhau", name: "Mordhau — 6 GB / 40 players", ramMB: 6144, cpuCores: 3, diskGB: 30, slots: 40, priceCents: 1299, featured: true },
  { gameFamily: "mordhau", name: "Mordhau — 8 GB / 64 players", ramMB: 8192, cpuCores: 4, diskGB: 40, slots: 64, priceCents: 1799 },

  // The Isle — dinosaur survival, heavy asset streaming + high current demand
  // (~13k avg CCU); priced above arkasa/icarus given the larger disk/RAM floor.
  { gameFamily: "theisle", name: "The Isle — 12 GB / 20 players", ramMB: 12288, cpuCores: 3, diskGB: 40, slots: 20, priceCents: 1899 },
  { gameFamily: "theisle", name: "The Isle — 16 GB / 30 players", ramMB: 16384, cpuCores: 4, diskGB: 50, slots: 30, priceCents: 2499, featured: true },
  { gameFamily: "theisle", name: "The Isle — 24 GB / 40 players", ramMB: 24576, cpuCores: 6, diskGB: 60, slots: 40, priceCents: 3299 },

  // Stationeers — small-crew space/factory sim, lightweight like Core Keeper.
  { gameFamily: "stationeers", name: "Stationeers — 4 GB / 4 players", ramMB: 4096, cpuCores: 2, diskGB: 20, slots: 4, priceCents: 899 },
  { gameFamily: "stationeers", name: "Stationeers — 6 GB / 8 players", ramMB: 6144, cpuCores: 2, diskGB: 25, slots: 8, priceCents: 1299, featured: true },
  { gameFamily: "stationeers", name: "Stationeers — 8 GB / 10 players", ramMB: 8192, cpuCores: 3, diskGB: 30, slots: 10, priceCents: 1699 },

  // Eco — civilization/economy sim, CPU + RAM heavy simulation even at modest
  // player counts; priced above abioticfactor given the official 8 GB+ floor.
  { gameFamily: "eco", name: "Eco — 8 GB / 12 players", ramMB: 8192, cpuCores: 3, diskGB: 25, slots: 12, priceCents: 1599 },
  { gameFamily: "eco", name: "Eco — 12 GB / 20 players", ramMB: 12288, cpuCores: 4, diskGB: 35, slots: 20, priceCents: 2199, featured: true },
  { gameFamily: "eco", name: "Eco — 16 GB / 24 players", ramMB: 16384, cpuCores: 6, diskGB: 45, slots: 24, priceCents: 2799 },

  // Empyrion — space sandbox, playfield memory usage scales with players;
  // priced in line with icarus/arkasa given the similar Wine-based RAM floor.
  { gameFamily: "empyrion", name: "Empyrion — 8 GB / 8 players", ramMB: 8192, cpuCores: 3, diskGB: 30, slots: 8, priceCents: 1499 },
  { gameFamily: "empyrion", name: "Empyrion — 12 GB / 12 players", ramMB: 12288, cpuCores: 4, diskGB: 40, slots: 12, priceCents: 1999, featured: true },
  { gameFamily: "empyrion", name: "Empyrion — 16 GB / 16 players", ramMB: 16384, cpuCores: 6, diskGB: 50, slots: 16, priceCents: 2599 },
];

async function main() {
  const templateIdByFamily = new Map<string, string>();
  let sort = 110;
  for (const t of TEMPLATES) {
    const os = await db.osTemplate.upsert({
      where: { slug: t.family },
      create: {
        slug: t.family, name: t.name, category: "APPLICATION", family: t.family, version: "", logo: t.family,
        vmid: 9000, baseVmid: 9000, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB,
        licenseRequired: false, featured: false, sortOrder: sort++, active: true,
      },
      update: { name: t.name, setupScript: t.setupScript, minRamMB: t.minRamMB, minDiskGB: t.minDiskGB, active: true },
    });
    templateIdByFamily.set(t.family, os.id);
    console.log(`  osTemplate ${t.family.padEnd(16)} → ${os.id}`);
  }

  const plans = await db.plan.findMany({ where: { active: true }, orderBy: { ramMB: "asc" } });
  if (plans.length === 0) throw new Error("No active VPS plans — run the main seed first.");
  const largest = plans[plans.length - 1];

  let created = 0, updated = 0;
  const sortByGame = new Map<string, number>();
  for (const spec of TIERS) {
    const basePlan = plans.find((p) => p.ramMB >= spec.ramMB) ?? largest;
    const osId = templateIdByFamily.get(spec.gameFamily) ?? null;
    const sortOrder = sortByGame.get(spec.gameFamily) ?? 0;
    sortByGame.set(spec.gameFamily, sortOrder + 1);
    const data = {
      gameFamily: spec.gameFamily, name: spec.name, ramMB: spec.ramMB, cpuCores: spec.cpuCores, diskGB: spec.diskGB,
      slots: spec.slots, priceCents: spec.priceCents, termMonths: 1, basePlanId: basePlan.id, osTemplateId: osId,
      featured: spec.featured ?? false, active: true, sortOrder,
    };
    const existing = await db.gamePlan.findFirst({ where: { gameFamily: spec.gameFamily, name: spec.name } });
    if (existing) { await db.gamePlan.update({ where: { id: existing.id }, data }); updated++; }
    else { await db.gamePlan.create({ data }); created++; }
    console.log(`  plan ${spec.name.padEnd(38)} base=${basePlan.name}`);
  }
  console.log(`\nWave 9: ${TEMPLATES.length} OsTemplates, GamePlans ${created} created / ${updated} updated.`);
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(() => db.$disconnect());

