import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, Wave 3 rollout.
 *
 * PREVIEW_GAMES.corekeeper was authored directly from the real seeded GamePlan
 * rows (prisma/seed-wave3-games.ts, 2026-08-31 — 2GB/6-player $4.99, 4GB/8-player
 * $7.99 popular, 6GB/8-player $11.99), so no price override is needed here.
 *
 * FAQ + related-links sections below follow the same pattern as
 * rust-server-hosting/page.tsx, since GameLandingCombined doesn't render its
 * own FAQ/related sections.
 */

export const metadata: Metadata = {
  title: "Core Keeper Server Hosting — Co-op Mining & Crafting, Instant Setup",
  description:
    "Managed Core Keeper server hosting from $4.99/mo. Full FTP access, custom world names, and instant setup on a low-latency Singapore network.",
