import type { GameFamily } from "./games";

/**
 * Modding info per game family — the content backing /game-servers/mods.
 *
 * Deliberately describes the REAL, well-established modding platform/loader
 * for each game (Oxide/uMod, BepInEx, Steam Workshop, tModLoader, …) rather
 * than naming specific third-party mods, which drift constantly and would go
 * stale or wrong. Nxeon doesn't curate or auto-install any of this — every
 * claim here is about ACCESS (full file/SFTP/console access, nothing
 * blocked), never about a one-click installer that doesn't exist. Keep it
 * that way: if a one-click mod installer ever ships for a family, say so
 * explicitly here rather than letting the general "full access" framing imply
 * more than is true.
 */
export type ModInfo = {
  /** The real platform/loader name shown as the card's badge. */
  platform: string;
  /** One sentence on how that platform works for this game. */
  blurb: string;
  /** Short honest note — access path, maturity caveat, etc. */
  note: string;
};

export const MOD_INFO: Record<GameFamily, ModInfo> = {
  minecraft: {
    platform: "Forge, Fabric, NeoForge & Paper/Spigot",
    blurb: "Every major Java Edition loader and plugin API is supported — swap the server jar and go.",
    note: "Upload via SFTP or the dashboard file manager; restart from the console when you're ready.",
  },
  bedrock: {
    platform: "Behavior & resource packs",
    blurb: "Bedrock's Add-Ons system (behavior + resource packs) instead of traditional Java mods.",
    note: "Drop packs straight into the world folder over SFTP.",
  },
  valheim: {
    platform: "BepInEx",
    blurb: "The standard Valheim mod loader — most community mods ship as BepInEx plugins.",
    note: "Install the loader once, then drop plugin DLLs into the plugins folder.",
  },

// Player-count → recommended resources, per game family. Pure/client-safe (no DB,
// no server-only imports) so the game deploy wizard's "how many players?" slider
// can compute a live recommendation with no round trip, the same way
// lib/custom-plan-pricing.ts prices the raw CPU/RAM/disk sliders.
//
// ─── DERIVATION ───────────────────────────────────────────────────────────────
// Every family already has 2-3 REAL, shipped tiers in the catalog (prisma/
// seed-gameplans.ts, seed-wave1-games.ts, seed-wave2-games.ts), each with actual
// ramMB/cpuCores/diskGB paired with a player-slot count. Rather than invent numbers
// from scratch, each family's curve below is a least-squares linear fit
// (resources = base + perPlayer × players) over that family's OWN seeded tiers —
// so within (and near) the range the catalog already sells, these numbers are
// GROUNDED in real, already-published specs, not guesses.
//
// Extrapolating the fitted line far PAST a family's largest seeded tier is where
// confidence drops — a straight line fit to 2-3 points at the low end is a rough
// estimate of what a much bigger population needs, not a measurement. That's
// exactly the case this slider exists for (a customer past the top of the normal
// tier ladder), so `maxSeededSlots` is recorded on every curve and
// `playerSliderMax` caps the slider at 5x it — generous enough to be useful for a
// genuinely large deployment, conservative enough that the recommendation is
// still a multiple-not-orders-of-magnitude extrapolation. See the design report
// for exactly which families' HIGH-player-count numbers are the least certain
// (the ones with only 2 seeded tiers, or a small `maxSeededSlots`) — the owner
// should sanity-check those before this ships, same as any new pricing surface.
//
// The recommendation is always a DEFAULT-SETTER, never a constraint: the caller
// (GameDeployWizard) applies it through clampCustomPlanSpec, so it can never
// itself produce a spec below the custom-plan floor (Max) or above the ceiling —
// the customer can still freely drag the underlying CPU/RAM/disk sliders above or
// below whatever this suggests.
import type { GameFamily } from "./games";

export type GameResourceSpec = { cpuCores: number; ramMB: number; diskGB: number };

type PlayerCurve = {
  ramBaseMB: number;
  ramPerPlayerMB: number;
  cpuBaseCores: number;
  cpuPerPlayer: number;
  diskBaseGB: number;
  diskPerPlayerGB: number;
  /** Largest slot count actually sold today for this family (see derivation note). */
  maxSeededSlots: number;
};

/**
 * Per-family curves, fitted from the live seeded catalog. Confidence notes:
 *
 * WELL-GROUNDED (3 seeded tiers spanning a wide slot range, so the fit is a real
 * interpolation more than an extrapolation): minecraft, rust, ark, satisfactory,
 * projectzomboid, sdtd, vrising, enshrouded, factorio, gmod, conan.
 *
 * ROUGHER (only 2 seeded tiers — the line is fixed by just two points, so treat
 * the slope itself as a reasonable-but-unverified estimate): valheim, palworld,
 * cs2, terraria, unturned, theforest, sonsoftheforest, bedrock.
 *
 * `enshrouded`'s raw 3-point least-squares fit produced a negative RAM/CPU
 * intercept (a fitting artifact, not a real "negative base machine") — clamped to
 * 0 here rather than left to produce a nonsensical recommendation at low player
 * counts.
 */
export const GAME_PLAYER_CURVES: Record<GameFamily, PlayerCurve> = {
  minecraft: { ramBaseMB: 788, ramPerPlayerMB: 150, cpuBaseCores: 1.6, cpuPerPlayer: 0.027, diskBaseGB: 14, diskPerPlayerGB: 0.73, maxSeededSlots: 50 },
