  terraria: { ramBaseMB: 0, ramPerPlayerMB: 256, cpuBaseCores: 0, cpuPerPlayer: 0.125, diskBaseGB: 10, diskPerPlayerGB: 1.25, maxSeededSlots: 16 },
  ark: { ramBaseMB: 1588, ramPerPlayerMB: 309, cpuBaseCores: 1.22, cpuPerPlayer: 0.049, diskBaseGB: 8, diskPerPlayerGB: 1.51, maxSeededSlots: 100 },

